('12', '0', '2026-06-16 10:23:52', '2026-06-16 10:23:52', '<!-- wp:hlm/hero {\"mediaType\":\"image\",\"mediaShowOverlay\":true,\"mediaOverlayStrength\":\"medium\",\"mediaImageUrl\":\"https://images.unsplash.com/photo-1523240795612-9a054b0db644?w=1920&#038;h=1080&#038;fit=crop\",\"mediaImageAlt\":\"Students collaborating on a university campus\",\"mediaPlaceholderLabel\":\"University Campus Video\",\"overline\":\"Education Lead Generation\",\"headline\":\"Connect Universities With Motivated U.S. Students\",\"description\":\"Higher Learning Marketers is a U.S.-focused education lead generation platform - helping universities fill nursing, business, and career programs while guiding students to accredited institutions that fit their goals.\",\"primaryCtaUrl\":\"#form\",\"secondaryCtaText\":\"University Services\",\"secondaryCtaUrl\":\"/services/\"} /-->\n\n<!-- wp:hlm/stats {\"variant\":\"bar\"} /-->\n\n<!-- wp:hlm/universities /-->\n\n<!-- wp:hlm/programs {\"anchor\":\"programs\"} /-->\n\n<!-- wp:hlm/process {\"variant\":\"home\",\"footerCtaText\":\"Get Started Now\",\"footerCtaUrl\":\"#form\",\"overline\":\"How It Works\",\"headline\":\"Three Simple Steps\",\"description\":\"Whether you are a student or institution, getting started takes just minutes.\",\"steps\":[{\"number\":\"01\",\"icon\":\"document\",\"title\":\"Submit Your Info\",\"description\":\"Fill out our simple form with your details, preferences, and goals. Takes less than 2 minutes.\",\"ctaText\":\"Start the Form\",\"ctaUrl\":\"#form\"},{\"number\":\"02\",\"icon\":\"info\",\"title\":\"Get Matched\",\"description\":\"Our system connects you with the best-fit programs or partnership opportunities based on your profile.\",\"ctaText\":\"Browse Programs\",\"ctaUrl\":\"#programs\"},{\"number\":\"03\",\"icon\":\"check\",\"title\":\"Start Your Journey\",\"description\":\"Connect directly with admissions teams or our partnership specialists to move forward.\",\"ctaText\":\"Get Started\",\"ctaUrl\":\"#form\"}]} /-->\n\n<!-- wp:hlm/testimonials {\"description\":\"Institutions and students trust us to deliver results.\"} /-->\n\n<!-- wp:hlm/blog /-->\n\n<!-- wp:hlm/cta {\"variant\":\"soft\",\"primaryText\":\"Join Now\",\"primaryUrl\":\"#form\",\"secondaryText\":\"See All Programs\",\"secondaryUrl\":\"/services/\",\"description\":\"Whether you are a student looking for the right program or an institution seeking qualified leads, we are here to help you succeed.\"} /-->', 'Home', 'Connect with top universities and programs. Find your perfect educational path or partner with us to reach motivated students.', 'publish', 'closed', 'closed', '', 'home', '', '', '2026-06-18 18:21:40', '2026-06-18 18:21:40', '', '0', 'https://higherlearningmarketers.com/home/', '0', 'page', '', '0'),
